INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('washing-machine-repair', 'Washing Machine Repair', 'Washing Machine', 'domestic', 'Washing machine and washer-dryer repair and installation — not draining, not spinning, leaks, noisy spin cycles, door faults and error codes.', '<p>A washing machine is one of the hardest-working appliances in the house, and when it stops mid-cycle, refuses to drain or leaves a puddle on the kitchen floor, everything else gets put on hold. Most faults come down to a handful of parts — the drain pump, door interlock, drive belt or motor brushes, heating element, inlet valves, drum bearings or the main control board. The key to a good repair is finding out which one has actually failed, rather than replacing parts on guesswork.</p>
<p>We repair freestanding and integrated washing machines and washer-dryers in homes across Feltham and West London. We also install new machines: connecting the cold supply and the waste, removing the transit bolts, levelling the machine and running a test cycle so you know it works before we leave.</p>
<h2>How we diagnose a washing machine fault</h2>
<p>We start by asking what the machine was doing when it stopped and checking any error code. Then we run the machine through its test modes, where the manufacturer provides them. Parts are tested with a meter rather than swapped on spec, so you only pay for parts that are actually needed.</p>
<p>If the fault is intermittent — say, a machine that only trips the electrics now and then — we''ll explain what we''ve found and the most likely cause, rather than guessing at an expensive part.</p>
<h2>Repair or replace?</h2>
<p>Pumps, door interlocks, belts, brushes, heating elements and hoses are generally worth replacing. Drum bearings are a bigger job. On many machines the tub is sealed, so the whole drum assembly has to be replaced, and that can make the repair poor value on a cheaper or older machine. Control boards sit somewhere in between, depending on the make and the price of the part.</p>
<p>We''ll always tell you which side of that line your machine falls on before any work goes ahead.</p>
<h2>Helping your washing machine last longer</h2>
<p>Clean the pump filter every few months. Leave the door and drawer open after use so the seal can dry out. Every so often, run an empty hot wash with a machine cleaner or descaler.</p>
<p>Don''t overload the drum, and check pockets before washing — small metal objects cause a surprising number of pump and drum repairs.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not draining', 'detail', 'Water left in the drum at the end of a cycle usually means a blockage in the filter, sump hose or pump, or a drain pump that has failed. Coins, hair grips and bra wires are common culprits.'), JSON_OBJECT('name', 'Drum not spinning', 'detail', 'The machine may be detecting an unbalanced load. Otherwise the cause could be worn motor brushes, a snapped drive belt, a faulty tacho sensor or a motor control fault.'), JSON_OBJECT('name', 'Leaking water', 'detail', 'Leaks can come from a split door seal, a loose or perished hose, a cracked detergent drawer housing, a failing pump seal or a damaged tub. Finding the exact source matters, because each one has a very different fix.'), JSON_OBJECT('name', 'Loud noise on spin', 'detail', 'Grinding or a roaring noise on spin is often worn drum bearings. Banging can mean a broken damper or suspension spring, or a counterweight that has worked loose.'), JSON_OBJECT('name', 'Door won''t open or lock', 'detail', 'Most machines won''t start until the door interlock confirms the door is locked. They also won''t release it until the drum is empty and the safety delay has passed. A failed interlock or handle mechanism stops either from happening.'), JSON_OBJECT('name', 'Not heating', 'detail', 'Clothes coming out cold or poorly washed can mean a failed heating element, a faulty temperature sensor or a control fault. Limescale on the element is a frequent cause in hard-water areas like West London.'), JSON_OBJECT('name', 'Error codes', 'detail', 'Modern machines store fault codes that point us in the right direction. We use them as a starting point, then test the parts involved to confirm the diagnosis.')), JSON_ARRAY(JSON_OBJECT('question', 'Is it worth repairing my washing machine or should I replace it?', 'answer', 'It depends on the fault, the age of the machine and the price of the parts. Many common faults — pumps, door locks, belts, heaters — are usually worth fixing. If a repair isn''t worth it, we''ll tell you honestly.'), JSON_OBJECT('question', 'My machine won''t drain. Can I get the water out myself?', 'answer', 'Yes, carefully. Switch the machine off at the wall, put towels down and hold a shallow tray under the pump filter, which is usually behind a small panel at the bottom front. Unscrew the filter slowly, because a lot of water can come out. Never open the door while the drum is full and the machine still has power.'), JSON_OBJECT('question', 'Can I keep using my machine if it''s leaking?', 'answer', 'We''d advise against it. Switch the machine off at the wall, close the water valve and don''t use it until it''s been checked. Leaks can damage flooring and create an electrical risk.'), JSON_OBJECT('question', 'Do you repair washer-dryers?', 'answer', 'Yes. We repair both the washing and drying functions of washer-dryers, including drying faults such as no heat or poor condensing.'), JSON_OBJECT('question', 'Can you install my new washing machine?', 'answer', 'Yes. We connect the water supply and waste, remove the transit bolts, level the machine and run a test cycle. [CONFIRM: whether you take away old appliances.]')), NULL, '/images/washing-machine-repair-feltham-800.webp', 'Front-loading washing machine in a bright laundry room', 'WashingMachine', 'Washing Machine Repair Feltham | Same-Day | HS Appliances', 'Washing machine repair in Feltham, Hounslow & West London. Not draining, not spinning, leaking or error codes? Same/next-day visits. Call 07777 372586.', 10, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('tumble-dryer-repair', 'Tumble Dryer Repair', 'Tumble Dryer', 'domestic', 'Tumble dryer repair for vented, condenser and heat-pump machines — not heating, not tumbling, long cycles, noise and door faults.', '<p>A tumble dryer that runs cold, takes hours to finish or stops mid-cycle leaves washing sitting wet. Most faults come down to the heater or heat pump, the drum belt or motor, the thermostat, the door switch, or a blocked filter and condenser.</p>
<p>We repair freestanding and integrated tumble dryers, including condenser and heat-pump models, in homes across Feltham and West London. We find the failed part before any work is agreed.</p>
<h2>Vented, condenser and heat pump</h2>
<p>A vented dryer pushes moist air outside through a hose. A condenser dryer collects that water in a tank or a drain hose. A heat-pump dryer reuses the heat and uses less electricity, but the sealed system needs proper testing if it stops drying.</p>
<p>Tell us which type you have when you book. The model plate is usually inside the door.</p>
<h2>Keeping it drying properly</h2>
<p>Clean the fluff filter after every load. On a condenser or heat-pump dryer, rinse the condenser or filter on the schedule in the manual. A blocked airway is the most common reason a dryer takes longer and longer.</p>
<p>Do not dry items that have been cleaned with flammable solvents, and do not leave the machine running when nobody is in.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not heating', 'detail', 'The drum turns but the clothes stay damp. On a vented or condenser dryer this is often the element, thermostat or thermal cut-out. On a heat-pump dryer it can be the compressor or a sensor.'), JSON_OBJECT('name', 'Not tumbling', 'detail', 'A snapped or slack drum belt, a worn motor or a failed capacitor will stop the drum turning. A jammed drum bearing can do the same and is usually noisy first.'), JSON_OBJECT('name', 'Taking too long to dry', 'detail', 'A blocked fluff filter, a packed condenser or a crushed vent hose makes the machine run for hours. A weak heater or a failing heat pump has the same result.'), JSON_OBJECT('name', 'Noisy', 'detail', 'A thump once per turn is often a worn drum roller or a foreign object. A squeal is more often the belt, a roller or the motor bearing.'), JSON_OBJECT('name', 'Will not start', 'detail', 'Check the door is shut. If it still will not start, the door switch, the start switch or the main board may have failed.'), JSON_OBJECT('name', 'Leaking or heavy condensation', 'detail', 'Condenser dryers leak when the condenser, pump or water container is blocked or cracked. The machine should be level, and the container seated properly.')), JSON_ARRAY(JSON_OBJECT('question', 'The drum turns but the clothes stay wet. What is wrong?', 'answer', 'The drum drive is working, so the fault is usually heat or airflow: the element, a thermostat, a blocked filter or condenser, or the heat pump on a heat-pump model.'), JSON_OBJECT('question', 'Do you repair washer-dryers as well as tumble dryers?', 'answer', 'Yes. Washer-dryer drying faults are covered with washing machine repairs. This page is for separate tumble dryers.'), JSON_OBJECT('question', 'Is it worth repairing an older dryer?', 'answer', 'Often yes, when the fault is a belt, element, switch or pump. After we have diagnosed it we will tell you if a repair is worth it before any work starts.')), NULL, '/images/washing-machine-drum-close-up-800.webp', 'Inside view of an empty laundry drum', 'Wrench', 'Tumble Dryer Repair Feltham | Same-Day | HS Appliances', 'Tumble dryer repair in Feltham & West London: not heating, not tumbling, long cycles or noisy. Vented, condenser and heat pump. Call 07777 372586.', 20, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('fridge-freezer-repair', 'Fridge Freezer Repair', 'Fridge Freezer', 'domestic', 'Fridge, freezer and fridge freezer repairs — not cooling, icing up, water inside, running constantly and noisy operation.', '<p>When a fridge freezer stops keeping food cold, the clock starts ticking. Food safety guidance is to keep a fridge at 5°C or below and a freezer at around -18°C. Once those temperatures slip, chilled food can become unsafe surprisingly quickly. The most common causes are electrical rather than catastrophic: a failed thermostat or temperature sensor, a fan that has stopped, a fault in the defrost system, a worn door seal or a faulty compressor start relay.</p>
<p>We repair freestanding and integrated fridges, freezers and fridge freezers, including frost-free models, for homes across Feltham and West London. We test the system to find out why it isn''t cooling, explain what we''ve found and talk you through your options before doing any work.</p>
<h2>Electrical faults vs. sealed-system faults</h2>
<p>Most fridge freezer faults are on the electrical side — thermostats, sensors, fans, defrost parts, relays and control boards. These are usually straightforward to replace, and often well worth doing.</p>
<p>Faults inside the sealed refrigeration system, such as a refrigerant leak or a compressor that has failed, are a different matter. They need specialist work and can cost more than a domestic appliance is worth. If that''s where the fault is, we''ll say so plainly and help you decide whether to repair or replace.</p>
<h2>What to do while you wait for a repair</h2>
<p>Keep the doors shut as much as possible — a closed freezer holds its temperature for a good while. Move the highest-risk foods (meat, fish, dairy, cooked leftovers) to a cool box or a neighbour''s fridge if you can. If food has been above 8°C for a long period, the safe option is to throw it away.</p>
<h2>Keeping your fridge freezer healthy</h2>
<p>Leave a gap behind and above the appliance so heat can escape, and vacuum the condenser coils at the back once or twice a year. Let leftovers cool before putting them in, and don''t pack shelves so tightly that air can''t circulate.</p>
<p>To check a door seal, close the door on a sheet of paper. If it slides out easily, the seal isn''t doing its job.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not cooling', 'detail', 'A fridge that has gone warm may have a failed thermostat, sensor or control board. It could also have a stopped fan or a compressor that isn''t starting. We work out which before recommending anything.'), JSON_OBJECT('name', 'Fridge warm, freezer fine', 'detail', 'In frost-free models the fridge is usually cooled by air from the freezer. If the evaporator ices over or the fan or air damper fails, the freezer keeps working while the fridge warms up.'), JSON_OBJECT('name', 'Freezer icing up', 'detail', 'Heavy frost build-up points to a defrost heater, timer or sensor fault in frost-free models, or warm air getting in past a damaged door seal.'), JSON_OBJECT('name', 'Water inside or underneath', 'detail', 'A blocked defrost drain is the classic cause of water collecting under the salad drawers. A split drain hose or a cracked evaporation tray can let water reach the floor.'), JSON_OBJECT('name', 'Running constantly', 'detail', 'A compressor that never switches off may be struggling because of dirty condenser coils, poor ventilation, a door seal leak or a faulty thermostat.'), JSON_OBJECT('name', 'Unusual noises', 'detail', 'Buzzing, rattling or squealing usually comes from a fan motor, the compressor mounts or an ice build-up touching a fan blade.'), JSON_OBJECT('name', 'Door seal problems', 'detail', 'A split, flattened or loose seal lets warm, humid air in, which causes icing, condensation and a fridge that runs all the time.')), JSON_ARRAY(JSON_OBJECT('question', 'What temperature should my fridge and freezer be?', 'answer', 'Keep the fridge between 0°C and 5°C and the freezer at around -18°C. A cheap fridge thermometer is the easiest way to check, as dial settings don''t show the actual temperature.'), JSON_OBJECT('question', 'My fridge has stopped cooling. What should I do first?', 'answer', 'Check it''s switched on, the temperature setting hasn''t been changed and the vents inside aren''t blocked by food. Keep the doors closed to hold in the cold, then call us to arrange a diagnosis.'), JSON_OBJECT('question', 'Why is there water at the bottom of my fridge?', 'answer', 'Usually it''s a blocked defrost drain, but it can also be a failing door seal or a defrost system fault. It''s normally quick to diagnose on site.'), JSON_OBJECT('question', 'Why is my fridge warm when the freezer is still freezing?', 'answer', 'In frost-free models the fridge relies on cold air from the freezer. An iced-up evaporator, a failed fan or a stuck air damper will stop that airflow. It''s a common, fixable fault.'), JSON_OBJECT('question', 'Do you repair integrated fridge freezers?', 'answer', 'Yes, we work on both freestanding and integrated models.')), NULL, '/images/fridge-freezer-repair-feltham-800.webp', 'Fridge freezer with the door open showing empty shelves', 'Refrigerator', 'Fridge Freezer Repair Feltham | Same-Day | HS Appliances', 'Fridge freezer repair in Feltham & West London: not cooling, icing up, leaking or noisy. Quote before any work. Same/next-day visits. Call 07777 372586.', 30, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('american-fridge-repair', 'American Fridge Freezer Repair', 'American Fridge', 'domestic', 'American-style fridge freezer repairs — cooling faults, ice makers, water dispensers, leaks and error codes on side-by-side and multi-door models.', '<p>American-style fridge freezers have a lot more going on than a standard fridge. As well as the cooling system, there''s usually an ice maker, a chilled water dispenser, a water inlet valve and filter, several fans and an electronic control panel. When something goes wrong, the first job is to work out which of those systems is at fault, because a leak, a warm fridge and an ice maker that''s stopped can all have overlapping causes.</p>
<p>We repair side-by-side, French-door and multi-door American fridge freezers, including plumbed-in models with filtered water and ice. Our engineers cover Feltham and the surrounding West London areas, and we''ll explain what''s wrong and what it will take to fix before starting any repair.</p>
<h2>Water and ice system faults</h2>
<p>Ice and water problems are the most common complaint with American fridges. Inlet valves need a minimum water pressure to open properly, so a weak supply can cause slow ice production or a trickling dispenser. A filter left in too long has the same effect.</p>
<p>In some designs the water line runs through the freezer door, and it can freeze if the door seal or the door heater has a problem. We check the whole route from the supply to the dispenser so the fix lasts.</p>
<h2>Positioning, levelling and installation</h2>
<p>American fridge freezers are heavy, and their doors are wide. If the cabinet isn''t level, or tilts very slightly forward rather than back, the doors may not close and seal by themselves. That leads to frost, condensation and a compressor that runs all the time.</p>
<p>They also need space around them to get rid of heat. If a unit has been moved or laid on its side, manufacturers generally recommend leaving it upright for a period before switching it on, so check your manual. We can help with installing and connecting the water supply on plumbed models.</p>
<h2>Is it worth repairing?</h2>
<p>Because American fridges are relatively expensive to replace, faults with fans, valves, sensors, ice makers and control boards are usually worth fixing. Sealed-system faults such as a refrigerant leak or a failed compressor need a more careful cost comparison. We''ll give you the information to make that call.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not cooling, or one side warmer', 'detail', 'Most American fridges cool both compartments from one evaporator, with fans and dampers moving the air around. A blocked air duct, a failed fan or an iced-up coil can leave one side warm.'), JSON_OBJECT('name', 'Ice maker not producing ice', 'detail', 'Check first that the ice maker is switched on. After that, the usual suspects are a frozen fill tube, a blocked water filter, low water pressure, a faulty inlet valve or a failed ice maker module.'), JSON_OBJECT('name', 'Water dispenser not working', 'detail', 'A frozen water line in the door, an overdue filter, a faulty dispenser switch or an inlet valve fault can all stop the flow. A dripping dispenser often points to a leaking valve.'), JSON_OBJECT('name', 'Leaking onto the floor', 'detail', 'Leaks can come from the water supply connection, a cracked filter housing, a split internal water line or a blocked defrost drain overflowing.'), JSON_OBJECT('name', 'Excessive frost', 'detail', 'Frost building up in the freezer usually means a defrost system fault or a door that isn''t sealing — on heavy doors this is sometimes a levelling problem rather than a bad seal.'), JSON_OBJECT('name', 'Noisy fans or compressor', 'detail', 'A grinding or ticking noise is often ice catching a fan blade. Loud humming can come from the compressor or the condenser fan at the back.'), JSON_OBJECT('name', 'Display or error codes', 'detail', 'Many models show diagnostic codes on the control panel. We read them and use the manufacturer''s test mode, where it has one, to narrow down the fault.')), JSON_ARRAY(JSON_OBJECT('question', 'Why has my ice maker stopped working?', 'answer', 'Common causes include a frozen water line, a blocked filter, a faulty inlet valve or a failed ice maker module. We find out which before replacing anything.'), JSON_OBJECT('question', 'How often should the water filter be changed?', 'answer', 'Most manufacturers recommend about every six months, but check your model''s manual. An overdue filter can reduce water flow and affect ice production.'), JSON_OBJECT('question', 'Why is my American fridge leaking water?', 'answer', 'Typical causes are a loose supply connection, a cracked filter housing, a split internal water line or a blocked defrost drain. Turn off the water supply to the fridge if you can, and dry the area to stop floor damage.'), JSON_OBJECT('question', 'Will you need to pull the fridge out?', 'answer', 'Usually, yes — many faults are only reachable from the back. Please clear a little space in front so it can be moved carefully. We take care to protect your flooring.'), JSON_OBJECT('question', 'Can you install a plumbed American fridge freezer?', 'answer', 'Yes, we can install and connect the water supply for plumbed-in models. [CONFIRM: remove if you don''t offer the plumbing connection.]')), NULL, '/images/american-fridge-freezer-repair-800.webp', 'Stainless steel American-style fridge freezer in a white fitted kitchen', 'Container', 'American Fridge Repair Feltham | Same-Day | HS Appliances', 'American fridge freezer repair in Feltham & West London — cooling faults, ice makers, water dispensers and leaks. Same/next-day visits. 07777 372586.', 40, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('dishwasher-repair', 'Dishwasher Repair', 'Dishwasher', 'domestic', 'Dishwasher repair and installation — not draining, poor cleaning, leaks, not heating or drying, and error codes on freestanding and integrated machines.', '<p>A dishwasher that leaves dirty plates, won''t drain or stops halfway through a cycle quickly turns a time-saver into a chore. Behind most faults is one of a few parts: the drain pump, the wash (circulation) pump, the heating element, the spray arms, the filters, the inlet valve or the electronic controller. Some faults are simple blockages, and others are a part that has worn out.</p>
<p>We repair freestanding, integrated and slimline dishwashers for homes across Feltham and West London, and we install new machines too. We''ll diagnose the fault and explain it in plain terms before carrying out any repair.</p>
<h2>Hard water and your dishwasher</h2>
<p>Most of West London has hard water, and limescale is a dishwasher''s enemy. It builds up on heating elements, in spray arms and in valves, cutting cleaning performance and shortening the life of parts. Keeping the salt reservoir topped up and setting the water-hardness level correctly in the machine''s settings makes a real difference.</p>
<p>Rinse aid isn''t optional on most modern machines either — they rely on it to dry dishes at lower temperatures.</p>
<h2>Integrated dishwasher repairs</h2>
<p>Integrated machines sit behind a kitchen door panel, and some faults need the machine sliding out of its housing. We disconnect and refit integrated dishwashers carefully, and we check the door springs and hinges too. A worn spring makes the heavy decor door drop open and puts strain on the hinges and the door seal.</p>
<h2>Simple maintenance that prevents repairs</h2>
<p>Clean the filter in the base every week or two — it takes less than a minute. Scrape plates before loading, but there''s no need to pre-rinse. Once a month, run an empty hot cycle with a dishwasher cleaner, and check the spray arms spin freely and their holes aren''t blocked.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not draining', 'detail', 'Standing water in the base usually comes from a clogged filter, a kinked or blocked waste hose, a blocked sink connection or a drain pump that has seized or failed.'), JSON_OBJECT('name', 'Dishes not coming out clean', 'detail', 'Blocked spray arm holes, a dirty filter, a weak wash pump, low water intake or a heating fault can all leave food residue and a gritty film on dishes.'), JSON_OBJECT('name', 'Leaking', 'detail', 'Water on the floor can come from a worn door seal, a cracked sump, a failed pump seal, a loose hose clamp or too much foam from the wrong detergent.'), JSON_OBJECT('name', 'Not heating or drying', 'detail', 'Cold, wet dishes at the end of a cycle point to a failed heating element or flow heater, a faulty temperature sensor, or a lack of rinse aid.'), JSON_OBJECT('name', 'Won''t start or stops mid-cycle', 'detail', 'A faulty door switch, a water supply problem, a tripped anti-flood system or a control fault can prevent a cycle from starting or finishing.'), JSON_OBJECT('name', 'Detergent not dispensing', 'detail', 'If tablets are left in the dispenser, the latch may be sticking or broken, or blocked spray arms may not be reaching the dispenser to dissolve the tablet.'), JSON_OBJECT('name', 'Error codes', 'detail', 'Error codes help us narrow down whether the fault is with water intake, draining, heating or leak detection before we start testing parts.')), JSON_ARRAY(JSON_OBJECT('question', 'Why won''t my dishwasher drain?', 'answer', 'Usually a blocked filter, a blocked waste hose or sink connection, or a faulty drain pump. Cleaning the filter is a good first check. If that doesn''t help, we can diagnose it.'), JSON_OBJECT('question', 'Why are my dishes still dirty after a cycle?', 'answer', 'Blocked spray arms, a clogged filter, a weak circulation pump or a heating fault are the usual culprits. Hard water and the wrong detergent can contribute too.'), JSON_OBJECT('question', 'Why is there white residue on my glasses?', 'answer', 'Often it''s limescale from hard water. Check the salt reservoir is full and the hardness setting is correct. If it persists, the water softener unit in the machine may need attention.'), JSON_OBJECT('question', 'Do you repair integrated dishwashers?', 'answer', 'Yes — integrated, freestanding and slimline models.'), JSON_OBJECT('question', 'Can you install a new dishwasher?', 'answer', 'Yes, including connecting the water supply and waste and fitting integrated machines into an existing housing. [CONFIRM: whether you fit decor panels.]')), NULL, '/images/dishwasher-repair-west-london-800.webp', 'Empty stainless steel dishwasher with the door open', 'UtensilsCrossed', 'Dishwasher Repair Feltham | Same-Day | HS Appliances', 'Dishwasher repair in Feltham & West London: not draining, not cleaning, leaking or not drying. Integrated & freestanding. Call 07777 372586.', 50, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('oven-repair', 'Oven Repair', 'Oven', 'domestic', 'Built-in and freestanding electric oven repair — not heating, uneven cooking, fan noise, grill faults, tripping electrics and failed controls.', '<p>An oven that stays cold, burns one side of the food or trips the electrics is usually a failed element, fan, thermostat, selector or door seal. Those parts are often replaceable, so the oven does not have to be written off.</p>
<p>We repair built-in single and double ovens and freestanding electric ovens for homes across Feltham and West London. The cooker is isolated and tested before any panels come off.</p>
<h2>Built-in ovens</h2>
<p>Built-in ovens sit in a housing and are usually on their own circuit, with an isolator above the worktop. The element, fan and thermostat are reached from inside the cavity or from the rear, depending on the make.</p>
<p>Have the make and model ready when you book. It is on a plate around the door frame.</p>
<h2>Using the oven safely</h2>
<p>Do not keep using an oven that trips the electrics. Switch it off at the wall isolator.</p>
<p>Do not line the floor of the oven with foil. It blocks the airflow and can damage the enamel and the lower element.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Oven not heating', 'detail', 'A failed fan element, a thermostat, a selector switch, a thermal cut-out or a timer that is not in manual mode can all leave the oven cold.'), JSON_OBJECT('name', 'Uneven cooking', 'detail', 'Food burning on one side often means the fan is slow or stopped, or the thermostat is out of range.'), JSON_OBJECT('name', 'Fan noisy or not running', 'detail', 'A worn fan motor squeals or grinds. If the fan stops, a fan oven heats unevenly and may cut out.'), JSON_OBJECT('name', 'Tripping the electrics', 'detail', 'An element that has failed to earth is the usual cause. Switch the oven off at the isolator and leave it off until it has been checked.'), JSON_OBJECT('name', 'Grill not working', 'detail', 'A failed grill element or grill control stops the grill while the main oven can still heat.'), JSON_OBJECT('name', 'Door not closing or heat escaping', 'detail', 'A perished seal or a tired hinge lets heat out, so food cooks slowly and the front of the oven gets hotter than it should.')), JSON_ARRAY(JSON_OBJECT('question', 'My oven trips the fuse. Can I reset it and carry on?', 'answer', 'No. Switch it off at the isolator and leave it off. Tripping usually means an element or the wiring has failed to earth.'), JSON_OBJECT('question', 'Do you repair electric ovens and cookers?', 'answer', 'Yes. We repair built-in electric ovens, freestanding electric ovens and electric cookers.'), JSON_OBJECT('question', 'The clock is flashing and the oven will not heat. Is that a fault?', 'answer', 'Often the oven is waiting for the clock to be set, or the timer is not in manual. If it still will not heat once the clock is set, the clock module or the controls may have failed.')), NULL, '/images/electric-oven-repair-800.webp', 'Electric fan oven lit up with food cooking inside', 'Wrench', 'Oven Repair Feltham | Same-Day | HS Appliances', 'Oven repair in Feltham & West London — not heating, fan faults, tripping electrics, grills and door seals. Call 07777 372586.', 60, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('electric-cooker-repair', 'Electric Cooker & Oven Repair', 'Electric Cooker', 'domestic', 'Electric cooker and oven repairs — not heating, uneven cooking, fan faults, grills, tripping electrics and broken timers or controls.', '<p>An oven that won''t heat up, burns food on one side or trips the electrics as soon as it''s switched on is more than an inconvenience. Electric ovens are fairly simple machines at heart — heating elements, a fan, a thermostat, a selector switch, a thermal cut-out and a timer or control board — so most faults can be traced to a specific part that''s often available to replace.</p>
<p>We repair freestanding electric cookers, built-in single and double ovens and range-style cookers for homes across Feltham and West London. Every repair starts with safe isolation and proper testing, so we fix the real cause instead of swapping parts until the problem goes away.</p>
<h2>Why the fan oven element fails</h2>
<p>In a fan oven, the element wraps around the fan behind the back panel. It works hard, heating up and cooling down every time the oven is used, and eventually it breaks or shorts to earth. When it shorts, the oven usually trips the electrics. When it breaks, the fan runs but the oven stays cold.</p>
<p>Replacing the element is one of the most common oven repairs we do, and it''s usually well worth doing.</p>
<h2>Electric cookers and safety</h2>
<p>Most electric cookers are hard-wired to a dedicated high-current circuit with its own isolator switch on the wall. That''s why oven repairs aren''t a good DIY job. The cooker must be safely isolated and tested before any panels come off.</p>
<p>If your oven trips the electrics, switch it off at the cooker isolator and leave it off until it''s been checked.</p>
<h2>Getting the best from your oven</h2>
<p>Don''t line the oven floor with foil — it blocks airflow and can damage the enamel and the bottom element. Clean the door seal gently, and keep harsh oven cleaners away from the seal, the fan and the control panel.</p>
<p>If your oven has a pyrolytic self-clean function, follow the manual and remove the shelves and runners first.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Oven not heating', 'detail', 'In a fan oven, the circular element behind the fan cover is the most common failure. A faulty thermostat, selector switch, thermal cut-out or timer can also stop the oven heating.'), JSON_OBJECT('name', 'Uneven cooking or burning', 'detail', 'If food burns on one side or the oven runs much hotter than the dial says, the thermostat may be out of calibration, or the fan may be running slowly or not at all.'), JSON_OBJECT('name', 'Fan not working or noisy', 'detail', 'A worn fan motor bearing causes grinding or squealing. A failed motor means the oven heats unevenly and may trip its safety cut-out.'), JSON_OBJECT('name', 'Tripping the electrics', 'detail', 'An element that has failed to earth is the usual reason an oven trips the circuit breaker or RCD. Damaged wiring or moisture in the terminal block are other causes.'), JSON_OBJECT('name', 'Grill not working', 'detail', 'A blown grill element, a faulty grill control or a selector switch fault will stop the grill heating while the main oven still works.'), JSON_OBJECT('name', 'Timer, clock or controls', 'detail', 'Many ovens won''t heat until the clock has been set or the timer is in manual mode. If the controls are unresponsive, the clock module or control board may have failed.'), JSON_OBJECT('name', 'Door seal or hinge damage', 'detail', 'A loose or perished door seal lets heat escape, so food cooks slowly and the controls and the front of the cooker get hotter than they should.')), JSON_ARRAY(JSON_OBJECT('question', 'My oven trips the electrics. Is it safe to use?', 'answer', 'No. Switch it off at the isolator and don''t use it until it''s been checked. Tripping usually points to a failed element or a wiring fault.'), JSON_OBJECT('question', 'Why does my fan run but the oven doesn''t heat?', 'answer', 'This is the classic sign of a failed fan oven element. It can also be a thermal cut-out or thermostat fault, so we test before replacing anything.'), JSON_OBJECT('question', 'Why won''t my oven work until I set the clock?', 'answer', 'On many ovens the timer controls the heating. After a power cut, the clock may need resetting or switching back to manual mode before the oven will heat.'), JSON_OBJECT('question', 'Do you repair built-in ovens?', 'answer', 'Yes — built-in single and double ovens as well as freestanding and range cookers.'), JSON_OBJECT('question', 'Can you install a new electric cooker?', 'answer', 'Yes. [CONFIRM: state whether you connect hard-wired cookers to an existing cooker point, and any electrical qualifications you hold.]')), NULL, '/images/electric-oven-repair-800.webp', 'Electric fan oven lit up with food cooking inside', 'CookingPot', 'Electric Cooker Repair Feltham | Same-Day | HS Appliances', 'Electric oven & cooker repair in Feltham & West London — not heating, fan faults, tripping electrics, grills and timers. Call 07777 372586.', 70, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('electric-hob-repair', 'Electric & Induction Hob Repair', 'Electric Hob', 'domestic', 'Ceramic, induction and solid-plate hob repairs — zones not heating, unresponsive touch controls, pan detection faults and error codes.', '<p>Electric hobs come in several types — ceramic (radiant), halogen, induction and traditional solid plate — and each fails in its own ways. A ceramic zone that won''t glow red is usually an element or energy regulator problem. An induction hob that beeps and shows an error, or won''t recognise your pans, more often points to a generator board, coil or cooling fan.</p>
<p>We repair all types of electric hob for homes across Feltham and West London. We''ll work out whether the fault is in a single zone, the control electronics or the power supply, explain it clearly, and quote before carrying out the repair.</p>
<h2>How induction hobs differ</h2>
<p>Induction hobs heat the pan directly using a magnetic field from copper coils under the glass, driven by power electronics called generator boards. Because those electronics produce heat, a cooling fan underneath keeps them within safe limits. If the fan fails or the ventilation gap under the hob is blocked, the hob may shut down or show overheating errors.</p>
<p>A faulty induction hob isn''t necessarily a write-off. Individual boards, coils and fans can often be replaced.</p>
<h2>If the glass is cracked</h2>
<p>Stop using the hob and switch it off at the isolator. A cracked top can let spills reach live parts underneath. We''ll check whether a replacement top is available for your model and whether it''s worth fitting compared with a new hob.</p>
<h2>Looking after a glass hob</h2>
<p>Wipe up sugary spills promptly, as they can pit the glass when they burn on. Use a proper hob scraper and cleaner rather than abrasive pads, and lift pans rather than sliding them.</p>
<p>For induction hobs, keep the ventilation space underneath clear. Avoid storing items in a drawer directly under the hob that could block the airflow.</p>', JSON_ARRAY(JSON_OBJECT('name', 'One or more zones not heating', 'detail', 'On ceramic hobs this is often a failed radiant element or energy regulator. On induction hobs it''s more likely a coil, a generator board or a connection between them.'), JSON_OBJECT('name', 'Touch controls not responding', 'detail', 'Water, grease or a pan resting on the control area can confuse touch sensors. If cleaning doesn''t help, the touch control board itself may have failed.'), JSON_OBJECT('name', 'Induction not detecting pans', 'detail', 'Induction needs magnetic cookware with a flat base. If suitable pans aren''t recognised, the coil, its temperature sensor or the generator may be faulty.'), JSON_OBJECT('name', 'Error codes or beeping', 'detail', 'Induction hobs protect themselves when they sense overheating, power problems or internal faults. The code helps us pinpoint the part responsible.'), JSON_OBJECT('name', 'Hob tripping the electrics', 'detail', 'A shorted element, a damaged terminal block or a failed power board can trip the breaker or RCD as soon as the hob is turned on.'), JSON_OBJECT('name', 'Cracked or chipped glass', 'detail', 'A crack in a ceramic or induction top is a safety issue. Replacing the glass means fitting a new top panel, which is available for many — but not all — models.')), JSON_ARRAY(JSON_OBJECT('question', 'Can I use my hob if the glass is cracked?', 'answer', 'No — switch it off at the isolator. A cracked glass top can expose live parts and should be replaced before you use it again.'), JSON_OBJECT('question', 'Why won''t my induction hob recognise my pan?', 'answer', 'Induction needs magnetic cookware with a flat base. Test your pan with a fridge magnet. If suitable pans aren''t detected, the fault may be a sensor, coil or control board.'), JSON_OBJECT('question', 'Why does my induction hob keep switching off?', 'answer', 'It may be overheating because of a failed cooling fan or blocked ventilation, or it may be detecting a power or internal fault. An error code helps us diagnose it quickly.'), JSON_OBJECT('question', 'Do you repair induction hobs?', 'answer', 'Yes — induction, ceramic, halogen and solid-plate electric hobs.')), NULL, '/images/induction-hob-repair-800.webp', 'Black induction hob set into a white kitchen worktop', 'Zap', 'Electric Hob Repair Feltham | Same-Day | HS Appliances', 'Induction, ceramic & electric hob repair in Feltham & West London: zones not heating, touch controls, error codes. Call 07777 372586.', 80, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('microwave-repair', 'Microwave Repair', 'Microwave', 'domestic', 'Microwave and combination oven repairs — not heating, turntable faults, sparking, door and touch-panel problems on built-in and freestanding models.', '<p>Microwaves look simple, but inside is a high-voltage circuit — a transformer, a capacitor, a diode and the magnetron that produces the microwaves. The capacitor can hold a dangerous charge even after the plug is pulled. That''s why microwave repairs should only be done by someone trained to discharge and test these parts safely.</p>
<p>We repair built-in microwaves, combination microwave ovens and higher-end freestanding models for homes across Feltham and West London. For basic freestanding microwaves, we''ll be upfront if a replacement makes more sense than a repair.</p>
<h2>Why microwave repairs aren''t DIY</h2>
<p>The high-voltage capacitor inside a microwave can store a charge that''s lethal, and it doesn''t always discharge when the plug is pulled. Door switches and seals also play a critical role in keeping microwave energy inside the cavity.</p>
<p>After any repair we check the door closes, latches and seals correctly, so the oven is safe to use as well as working again.</p>
<h2>Built-in and combination microwaves</h2>
<p>Built-in and combination microwaves — the kind that also grill and bake using a convection element — cost considerably more than countertop models and are fitted into kitchen units. That usually makes a repair the sensible choice.</p>
<p>The grill element, convection fan and combination controls add a few more possible faults, all of which we can test.</p>
<h2>Repair or replace — an honest view</h2>
<p>A new magnetron or control board can cost more than a basic freestanding microwave is worth. We''ll tell you when that''s the case rather than carrying out a repair that doesn''t make financial sense.</p>
<p>For built-in and combination models, most faults are usually worth repairing.</p>
<h2>Simple care tips</h2>
<p>Never run a microwave empty, keep metal out of the cavity and wipe splashes off the waveguide cover (the small panel on the inside wall). To loosen stubborn grime, heat a bowl of water with lemon juice for a few minutes, then wipe the inside clean.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Runs but doesn''t heat', 'detail', 'The light comes on and the turntable spins, but food stays cold. This usually points to the magnetron, high-voltage diode, capacitor or a door switch fault.'), JSON_OBJECT('name', 'Turntable not turning', 'detail', 'Check the roller ring and coupler are seated properly. If they are, the small turntable motor underneath may have failed.'), JSON_OBJECT('name', 'Sparking or arcing', 'detail', 'Metal in the cavity, a damaged or greasy waveguide cover, or chipped interior paint can cause sparking. Stop using it until it''s been checked.'), JSON_OBJECT('name', 'Won''t start or door problems', 'detail', 'Microwaves use several door interlock switches for safety. If any fail, or the door latch is damaged, the oven won''t start or may blow its internal fuse.'), JSON_OBJECT('name', 'Touch panel unresponsive', 'detail', 'Moisture, a worn membrane keypad or a control board fault can make buttons stop working, work intermittently or trigger the wrong functions.'), JSON_OBJECT('name', 'Blowing fuses or tripping', 'detail', 'A microwave that blows its fuse or trips the electrics may have a failed door switch, a shorted component in the high-voltage circuit or a wiring fault.')), JSON_ARRAY(JSON_OBJECT('question', 'Is it worth repairing a microwave?', 'answer', 'Built-in and combination microwaves are often worth repairing. For basic freestanding models, replacement may be cheaper — we''ll tell you honestly.'), JSON_OBJECT('question', 'Why is my microwave running but not heating?', 'answer', 'Usually a failed magnetron, high-voltage diode or capacitor, or a faulty door switch. These parts carry high voltage and should only be tested by a trained engineer.'), JSON_OBJECT('question', 'Why is my microwave sparking?', 'answer', 'Often metal in the cavity, a damaged waveguide cover or a build-up of food residue. Stop using it until it''s been checked.'), JSON_OBJECT('question', 'Can I keep using my microwave if the door is damaged?', 'answer', 'No. The door, its seal and its interlock switches keep microwave energy inside the oven. A damaged door should be repaired before the microwave is used again.'), JSON_OBJECT('question', 'Do you repair built-in microwaves?', 'answer', 'Yes, including built-in combination microwave ovens.')), NULL, '/images/microwave-repair-800.webp', 'Built-in microwave above an oven in a modern kitchen', 'Microwave', 'Microwave Repair Feltham | Same-Day | HS Appliances', 'Built-in & combination microwave repair in Feltham & West London — not heating, sparking, turntable or door faults. Call 07777 372586.', 90, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('air-conditioning-repair', 'Air Conditioning Repair & Servicing', 'Air Conditioning', 'domestic', 'Air conditioning repair and servicing for homes, shops and offices — not cooling, water leaks, noise, smells and error codes.', '<p>Air conditioning tends to be forgotten until the first hot week of the year — and that''s when faults show up. Weak cooling, water dripping from the indoor unit, strange smells or a system that won''t start are often caused by a lack of maintenance: clogged filters, dirty coils or a blocked condensate drain. Others come from failed fan motors, sensors, control boards or a loss of refrigerant.</p>
<p>We repair and service wall-mounted split systems, multi-split systems and portable air conditioners in homes, shops and offices across Feltham and West London. We''ll diagnose the fault, explain it clearly and recommend the right fix.</p>
<h2>What an air conditioning service includes</h2>
<p>A proper service covers cleaning or replacing filters, cleaning the indoor coil and fan, clearing and testing the condensate drain, cleaning the outdoor unit''s coil, checking electrical connections and controls, and checking the system''s performance.</p>
<p>Regular servicing keeps the system running efficiently, cuts the risk of breakdowns and helps keep the air that comes out of it clean.</p>
<h2>Refrigerant and the law</h2>
<p>Most air conditioning systems use fluorinated refrigerant gases (F-gases). In the UK, anyone who handles them — for example to find leaks, recover or recharge refrigerant — must be properly certified. If a system has lost refrigerant, the leak must be found and repaired, not just topped up.</p>
<h2>For homes and businesses</h2>
<p>In a home, air conditioning is usually a matter of comfort. In a shop, salon, office or server cupboard, a failed system can affect staff, customers and equipment.</p>
<p>We work on systems in both domestic and commercial settings. [CONFIRM: types and sizes of commercial systems you service.]</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not cooling or blowing warm air', 'detail', 'Dirty filters and coils, an outdoor unit that isn''t running, a faulty sensor or a low refrigerant charge can all stop a system cooling effectively.'), JSON_OBJECT('name', 'Water leaking indoors', 'detail', 'Most indoor leaks come from a blocked condensate drain or tray. A dirty filter can also make the coil freeze and then drip as it thaws.'), JSON_OBJECT('name', 'Noise or vibration', 'detail', 'Rattling, buzzing or squealing can come from a loose panel, a failing fan motor bearing, debris in the outdoor fan or worn anti-vibration mounts.'), JSON_OBJECT('name', 'Bad smells', 'detail', 'Musty smells usually mean mould or bacteria on the indoor coil, filters or drain tray. It''s a sign the system is overdue a clean.'), JSON_OBJECT('name', 'Won''t turn on or controls not responding', 'detail', 'Start with the remote batteries and the power supply. After that, it could be a receiver board, main control board or wiring fault between the indoor and outdoor units.'), JSON_OBJECT('name', 'Ice on pipework', 'detail', 'Frost on the pipes or the outdoor unit usually points to restricted airflow or a refrigerant problem. The system shouldn''t keep running in that state.'), JSON_OBJECT('name', 'Error codes', 'detail', 'Most systems show fault codes on the indoor unit or remote. They help us find the fault quickly, but we still test to confirm it.')), JSON_ARRAY(JSON_OBJECT('question', 'How often should air conditioning be serviced?', 'answer', 'Typically once a year for domestic systems, and more often for commercial units that are in heavy use. Check your manufacturer''s recommendations.'), JSON_OBJECT('question', 'Why is my air conditioner leaking water?', 'answer', 'Most often a blocked condensate drain, or a dirty filter causing the coil to freeze and then drip. It''s usually quick to resolve.'), JSON_OBJECT('question', 'Can you top up the gas in my air conditioning?', 'answer', 'If a system is low on refrigerant there''s a leak somewhere — refrigerant isn''t used up. The leak should be found and repaired before recharging, by an F-gas certified engineer.'), JSON_OBJECT('question', 'Do you install air conditioning?', 'answer', '[CONFIRM: state whether you install new systems and which types.]')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/air-conditioning-repair-800.webp', 'Outdoor air conditioning condenser unit beside a building', 'AirVent', 'Air Conditioning Repair Feltham | Same-Day | HS Appliances', 'Air conditioning repair & servicing in Feltham & West London for homes, shops and offices: not cooling, leaks, noise. Call 07777 372586.', 100, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('cold-room-repair', 'Cold Room Repair & Maintenance', 'Cold Room', 'commercial', 'Walk-in cold room and freezer room repairs and maintenance for restaurants, takeaways, shops and food businesses.', '<p>For a restaurant, takeaway, butcher or food shop, the cold room holds most of the stock. When it starts running warm, you''re looking at a food safety problem, a stock-loss problem and possibly a trading problem all at once. In England, chilled food must by law be kept at 8°C or below, and most businesses aim for 5°C or lower. A cold room that can''t hold that needs attention fast.</p>
<p>We diagnose and repair walk-in chillers and freezer rooms for businesses across Feltham and West London. We trace the fault through the whole system — condensing unit, evaporator, controls, door and defrost — and explain clearly what''s wrong and what it will take to fix.</p>
<h2>How a cold room system works</h2>
<p>A typical cold room has an evaporator unit inside, which blows cold air through the room, and a condensing unit outside or in a plant area, which rejects the heat. Between them are the refrigerant pipework and an expansion valve, and an electronic controller that manages temperature and defrost cycles.</p>
<p>A fault in any one of those can show up as the same symptom — a room that won''t hold temperature. That''s why systematic diagnosis matters.</p>
<h2>Planned maintenance</h2>
<p>Most cold room breakdowns build up over time. A condenser clogged with grease and dust makes the compressor work harder. Drain lines block, door seals tear and defrost settings drift.</p>
<p>Routine maintenance — cleaning coils, checking electrical connections, testing defrost operation, inspecting seals and verifying controller probes — catches these problems before they turn into a breakdown on a busy Friday. [CONFIRM: describe any maintenance plans you offer.]</p>
<h2>If your cold room fails</h2>
<p>Keep the door closed and record the temperature and the time. Move high-risk stock to other refrigeration if you can, and call us. Keeping a written record of temperatures and the actions you took supports your food safety management system and any conversation with your environmental health officer.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not holding temperature', 'detail', 'A cold room creeping up in temperature can be caused by a dirty condenser, a failing compressor or fan, an iced evaporator, a controller fault, a refrigerant leak or a door left ajar.'), JSON_OBJECT('name', 'Evaporator icing up', 'detail', 'Ice building on the evaporator coil inside the room usually means a defrost fault — a heater, timer, controller setting or drain-line problem — or warm, humid air getting in.'), JSON_OBJECT('name', 'Compressor short-cycling or not starting', 'detail', 'A compressor that keeps starting and stopping, or won''t run at all, may have an electrical fault, a pressure switch tripping or an overheating problem caused by poor condenser airflow.'), JSON_OBJECT('name', 'Door seals and heaters', 'detail', 'Damaged door gaskets, a door that doesn''t close by itself or a failed door-frame heater on a freezer room let warm air and moisture in, causing ice and high running costs.'), JSON_OBJECT('name', 'Alarm or controller faults', 'detail', 'High-temperature alarms, faulty probes and controllers with the wrong settings can cause false alarms or, worse, hide a real temperature problem.'), JSON_OBJECT('name', 'Water leaking inside', 'detail', 'A blocked or frozen evaporator drain line can send defrost water onto the floor or stock — a slip hazard as well as a hygiene issue.')), JSON_ARRAY(JSON_OBJECT('question', 'What should I do if my cold room stops cooling?', 'answer', 'Keep the door closed, record the temperature, move high-risk stock to other refrigeration if possible and call us straight away.'), JSON_OBJECT('question', 'What temperature should a cold room be?', 'answer', 'Chilled food must legally be kept at 8°C or below in England, and most businesses run chillers between 0°C and 5°C. Freezer rooms typically run at -18°C or colder.'), JSON_OBJECT('question', 'Do you work on walk-in freezers as well as chillers?', 'answer', 'Yes — both walk-in chillers and freezer rooms.'), JSON_OBJECT('question', 'Do you offer planned maintenance for cold rooms?', 'answer', '[CONFIRM: describe your maintenance offering.]')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/cold-room-repair-800.webp', 'Frozen stock stored in metal cages inside a commercial cold store', 'Warehouse', 'Cold Room Repair Feltham | Same-Day | HS Appliances', 'Cold room & walk-in freezer repair and maintenance for West London food businesses. Not holding temperature? Call 07777 372586.', 110, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('dairy-cabinet-repair', 'Dairy Cabinet Repair', 'Dairy Cabinet', 'commercial', 'Multideck dairy cabinet repairs for convenience stores, off-licences and supermarkets — warm cabinets, icing, fans, lighting and night blinds.', '<p>Open-front multideck dairy cabinets are the workhorses of convenience stores and supermarkets. They hold milk, cheese, yoghurt, cooked meats and drinks at chilled temperatures with no doors at all. They manage it by blowing a curtain of cold air down the front of the cabinet, and that air curtain is easily disrupted. When it''s disturbed, or a part fails, the cabinet warms up quickly and stock is at risk.</p>
<p>We repair multideck dairy cabinets and chilled displays for shops across Feltham and West London. We find out why a cabinet is running warm or icing up, and get it back to a safe temperature.</p>
<h2>Air curtains and load lines</h2>
<p>Every multideck has a load line marked on the shelves or sides. Stacking stock past it, or letting packaging hang over the front edge, breaks up the air curtain. Then warm shop air spills in and the cabinet can''t keep up.</p>
<p>Before calling for a repair, it''s worth checking the cabinet is loaded correctly and the honeycomb grilles at the top and bottom aren''t blocked.</p>
<h2>Integral vs. remote cabinets</h2>
<p>Integral (plug-in) cabinets have their own compressor and condenser built in and release heat into the shop. Remote cabinets are connected by pipework to a condensing unit outside or in a plant room.</p>
<p>The faults and repairs differ between the two, and we work on both types.</p>
<h2>Night blinds and running costs</h2>
<p>Open cabinets lose a lot of cold air overnight when the shop is closed. Night blinds cut that loss considerably, so a broken blind that''s been left up is quietly raising your energy bill.</p>
<p>Keeping the condenser coils clean, the blinds working and the fans running all help a cabinet run efficiently.</p>
<h2>Temperature checks and food safety</h2>
<p>Chilled food in England must legally be kept at 8°C or below, and most retailers aim lower. Checking cabinet temperatures at least twice a day — and writing them down — helps you spot a cabinet that''s starting to struggle and shows that you''re managing food safety properly.</p>
<p>If a cabinet is running warm, move high-risk products such as cooked meats and dairy to working refrigeration while you wait for a repair.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Cabinet running warm', 'detail', 'Overloaded shelves blocking the air curtain, an iced evaporator, failed fans, a dirty condenser or a controller fault are the most common causes.'), JSON_OBJECT('name', 'Evaporator icing up', 'detail', 'Ice on the coil at the bottom or back of the cabinet points to a defrost problem, blocked airflow or very humid conditions in the store.'), JSON_OBJECT('name', 'Fans not running', 'detail', 'Multidecks rely on evaporator fans to create the air curtain. One failed fan can leave part of the cabinet noticeably warmer than the rest.'), JSON_OBJECT('name', 'Lighting or night blind faults', 'detail', 'Failed LED strips, drivers or a night blind that won''t pull down or retract are common. A missing night blind adds a lot to overnight running costs.'), JSON_OBJECT('name', 'Water on the shop floor', 'detail', 'A blocked drain or a failing condensate evaporator tray can let defrost water spill out — a slip hazard for customers and staff.'), JSON_OBJECT('name', 'Noisy compressor or condenser', 'detail', 'On integral (plug-in) cabinets, a noisy compressor or condenser fan is often a warning sign of a failing bearing or a condenser that''s struggling to shed heat.')), JSON_ARRAY(JSON_OBJECT('question', 'Why is my dairy cabinet running warm?', 'answer', 'Air curtains blocked by overfilled shelves, iced evaporators, failed fans or dirty condensers are the common causes. We check each one in turn.'), JSON_OBJECT('question', 'Do you repair remote and integral cabinets?', 'answer', 'Yes, both types.'), JSON_OBJECT('question', 'My cabinet is leaking water onto the floor — what causes that?', 'answer', 'Usually a blocked drain or a fault with the condensate evaporator tray. Put a warning sign out, mop the area and call us to clear and check it.'), JSON_OBJECT('question', 'Can you help keep cabinets running efficiently?', 'answer', 'Yes. Regular condenser cleaning, and checks on seals, blinds, fans and controllers, help both efficiency and reliability.')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/dairy-cabinet-repair-800.webp', 'Rows of refrigerated dairy display cabinets in a grocery store', 'Milk', 'Dairy Cabinet Repair Feltham | Same-Day | HS Appliances', 'Multideck dairy cabinet repair for shops in Feltham, Hounslow & West London — running warm, icing, fans, night blinds. Call 07777 372586.', 120, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('display-fridge-repair', 'Display Fridge Repair', 'Display Fridge', 'commercial', 'Commercial display fridge repairs — glass-door drinks merchandisers, serve-over counters, cake and deli displays.', '<p>Display fridges do two jobs at once: they keep stock at a safe temperature, and they keep it looking good enough to sell. A merchandiser with misted-up doors, a serve-over counter that''s running warm or a cake display with failed lighting affects your takings as well as your food safety records.</p>
<p>We repair upright glass-door merchandisers, serve-over deli and butcher counters, patisserie and cake displays, and countertop chillers for cafés, shops, restaurants and takeaways across Feltham and West London. We''ll find the fault, explain it, and quote before carrying out the repair.</p>
<h2>Glass-door merchandisers</h2>
<p>Upright drinks and food merchandisers are often placed near entrances or windows, where sunlight and draughts make them work harder. Most have a fan-assisted evaporator at the top or back and a condenser at the bottom that pulls in air from the front grille.</p>
<p>When that grille gets clogged with dust, cooling performance drops and the compressor runs for longer.</p>
<h2>Serve-over counters</h2>
<p>Serve-over counters used by delis, butchers and fishmongers can be fan-assisted or static (gravity) cooled. Static counters keep fresh produce from drying out, but they''re more sensitive to how they''re loaded and to warm air around them.</p>
<p>We check the cooling system, the controls, the lighting and the glass to keep the counter at temperature and looking right.</p>
<h2>Keeping display fridges reliable</h2>
<p>Clean the condenser grille regularly, keep the area around the fridge clear for airflow, don''t block internal air vents with stock, and check door gaskets for splits.</p>
<p>Keeping a simple daily temperature log also helps spot a problem early, before it becomes a breakdown.</p>
<h2>Cake and patisserie displays</h2>
<p>Cake displays have to keep cream, custard and fruit products cold while staying clear enough to show them off. That means a balance between cooling and humidity: too dry and products crust over, too humid and the glass mists up.</p>
<p>Faults with fans, heaters, lighting and controllers all affect that balance. Curved-glass units also need careful handling when panels are removed for access, and we take that care when working on them.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not cooling to temperature', 'detail', 'A dirty condenser, a failed fan, a faulty thermostat or controller, an iced evaporator or a refrigerant leak can all leave a display fridge running warm.'), JSON_OBJECT('name', 'Condensation on glass', 'detail', 'Doors misting up — inside or out — usually points to high humidity, a worn door gasket, or a failed glass or frame heater on models that have them.'), JSON_OBJECT('name', 'Ice on the back wall', 'detail', 'Ice forming on the rear panel or around the evaporator suggests a defrost problem, a door that isn''t closing, or stock pressed against the evaporator.'), JSON_OBJECT('name', 'Fan or lighting failure', 'detail', 'Failed evaporator fans cause warm spots, and failed LED lighting makes the display look closed. Both are usually straightforward to replace.'), JSON_OBJECT('name', 'Doors not closing', 'detail', 'Worn hinges, broken self-closing mechanisms and damaged gaskets let doors drift open, which wastes energy and lets warm air in.'), JSON_OBJECT('name', 'Controller faults', 'detail', 'Incorrect set-points, faulty probes or a failing controller can make temperatures swing or set off false alarms.')), JSON_ARRAY(JSON_OBJECT('question', 'Why is my display fridge door misting up?', 'answer', 'Usually high humidity, a failing door seal or a faulty door heater. Persistent misting should be checked.'), JSON_OBJECT('question', 'What temperature should a display fridge run at?', 'answer', 'Chilled food must legally be kept at 8°C or below in England. Many businesses aim for 5°C or below to give a safety margin.'), JSON_OBJECT('question', 'Do you repair serve-over counters?', 'answer', 'Yes, as well as upright glass-door merchandisers and cake displays.'), JSON_OBJECT('question', 'Can you get parts for older models?', 'answer', 'We''ll source parts where they''re available, and tell you honestly if a unit is no longer worth repairing.')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/display-fridge-repair-800.webp', 'Glass-door display fridges stocked with chilled drinks', 'Store', 'Display Fridge Repair Feltham | Same-Day | HS Appliances', 'Display fridge repair for cafés, shops & delis in West London: glass-door merchandisers, serve-overs, cake displays. Call 07777 372586.', 130, 1, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('bar-cooler-repair', 'Bar Cooler Repair', 'Bar Cooler', 'commercial', 'Back-bar bottle cooler repairs for pubs, bars, clubs and restaurants — warm drinks, constant running, noisy fans, door and lighting faults.', '<p>Back-bar bottle coolers live a hard life. They''re usually squeezed under a counter with little room to breathe, surrounded by heat from glasswashers, lighting and people, and opened hundreds of times on a busy night. It''s no surprise they''re one of the most common pieces of bar equipment to fail — and warm drinks on a Friday night are bad for business.</p>
<p>We repair single, double and triple-door back-bar coolers, with hinged or sliding doors, for pubs, bars, clubs, restaurants and hotels across Feltham and West London. We''ll get to the cause of the problem and advise honestly on whether a unit is worth repairing.</p>
<h2>Heat and ventilation behind the bar</h2>
<p>Most bar coolers are designed to draw air in and blow it out through the front grille, so they can sit tight under a counter. If that grille is blocked by kick boards, crates or a build-up of dust, the condenser can''t get rid of heat, and the cooler runs warm and wears out early.</p>
<p>Some models need space at the back or sides instead. Fitting a cooler that doesn''t suit the space is a common cause of repeated breakdowns, and we''ll point it out if we see it.</p>
<h2>Hinged vs. sliding doors</h2>
<p>Sliding doors save space in narrow bars, but their runners, rollers and brushes wear out. Hinged doors seal well but depend on gaskets and self-closing hinges in good condition. Either way, worn door parts are often a cheap fix that makes a noticeable difference to cooling and running costs.</p>
<h2>Repair or replace?</h2>
<p>Fans, thermostats, controllers, lights and door parts are usually well worth replacing. A failed compressor or a refrigerant leak on an older, cheaper cooler may not be. We''ll explain the costs either way so you can decide what makes sense for your bar.</p>
<h2>Running costs</h2>
<p>Bar coolers often run around the clock, so a struggling unit costs money long before it actually breaks down. A clogged condenser, split door gaskets or a failing fan can all make the compressor run far longer than it should.</p>
<p>Some venues switch coolers off overnight to save energy. If you do, give them enough time to pull back down to temperature before service, and avoid loading them with warm stock just before opening.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Drinks not cold enough', 'detail', 'The usual causes are a clogged condenser, blocked ventilation, a failed condenser or evaporator fan, a faulty thermostat or a refrigerant leak.'), JSON_OBJECT('name', 'Running constantly', 'detail', 'A cooler that never cycles off is struggling to reject heat. That''s often down to dirt, poor airflow under the bar, or doors and seals letting warm air in.'), JSON_OBJECT('name', 'Noisy fan or compressor', 'detail', 'Rattling or grinding often means a worn fan motor or a fan blade catching. A loud compressor may be working too hard or failing.'), JSON_OBJECT('name', 'Doors not closing or worn seals', 'detail', 'Sliding door runners wear, hinges and self-closers fail and gaskets split, letting cold air out every time the bar is busy.'), JSON_OBJECT('name', 'Lighting not working', 'detail', 'LED strips and drivers fail over time. Bottle coolers are as much about display as cooling, so dark shelves affect sales.')), JSON_ARRAY(JSON_OBJECT('question', 'Why is my bar cooler not getting cold?', 'answer', 'A dirty condenser, poor ventilation behind the bar, a failed fan or a thermostat fault are the most common causes.'), JSON_OBJECT('question', 'How can I help my bar cooler last longer?', 'answer', 'Keep the front grille clear and clean, avoid stacking crates against it, don''t overload the shelves, and have the condenser cleaned regularly.'), JSON_OBJECT('question', 'Do you repair glass-door and solid-door bar coolers?', 'answer', 'Yes, both — hinged and sliding door models.'), JSON_OBJECT('question', 'Can you come outside of opening hours?', 'answer', '[CONFIRM: state whether you offer early, late or out-of-hours visits for pubs and bars.]')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/bar-cooler-repair-800.webp', 'Bottles of beer chilling on a glass shelf in a bar cooler', 'Beer', 'Bar Cooler Repair Feltham | Same-Day | HS Appliances', 'Bar & bottle cooler repair for pubs, bars and restaurants in Feltham & West London — warm drinks, noisy fans, door faults. 07777 372586.', 140, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('cellar-cooler-repair', 'Cellar Cooler Repair', 'Cellar Cooler', 'commercial', 'Beer cellar cooling repairs for pubs and bars — cellars running warm, iced evaporators, condensing unit and fan faults.', '<p>Beer quality starts in the cellar. Cask ale in particular needs a steady cellar temperature — industry guidance commonly gives 11–13°C — to condition properly and serve well. A cellar that drifts too warm quickly leads to fobbing, hazy or flat beer and wasted product. And because the cellar is out of sight, a failing cooling system often isn''t noticed until customers start complaining.</p>
<p>We repair cellar cooling systems for pubs, bars, clubs and restaurants across Feltham and West London. We diagnose evaporators, condensing units, fans and controllers, and explain the fault and the fix before starting work.</p>
<h2>How cellar cooling works</h2>
<p>Most pub cellars use a split system: an evaporator unit mounted in the cellar, connected to a condensing unit outside — often in a yard, a light well or on a wall. Through-the-wall units combine both parts in one.</p>
<p>Either way, the system relies on clean coils, working fans and a reasonably sealed, insulated cellar to hold a stable temperature.</p>
<h2>Heat load and busy periods</h2>
<p>Cellar cooling has more to cope with than outside temperature. Beer line coolers and ice-bank chillers often sit in or near the cellar and give off heat. Deliveries mean the doors are opened for long periods, and summer heat makes the condensing unit work harder.</p>
<p>A system that copes in spring can struggle in July, which is why maintenance before summer is a good idea.</p>
<h2>Looking after your cellar cooler</h2>
<p>Keep the outdoor unit free of leaves, litter and anything stacked against it. Keep cellar doors and hatches closed, and avoid storing cardboard and clutter in front of the evaporator.</p>
<p>If you notice ice on the cooler, water dripping or the temperature creeping up, get it looked at early rather than waiting for it to fail.</p>
<h2>Early warning signs</h2>
<p>Cellar cooling rarely fails without warning. Watch out for the cellar thermometer creeping up through the day, ice forming on the evaporator fins, water dripping from the unit, the condensing unit outside running constantly or cycling on and off rapidly, and beer that starts fobbing at the tap even though nothing else has changed.</p>
<p>Any of these is a good reason to have the system checked before a hot weekend turns a minor fault into lost stock.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Cellar running warm', 'detail', 'A dirty or obstructed condensing unit, a failed fan, a controller fault, a refrigerant leak or a cellar door left open can all push the temperature up.'), JSON_OBJECT('name', 'Evaporator icing up', 'detail', 'Ice on the cellar cooler coil restricts airflow and cooling. It usually points to low airflow, a defrost issue, a dirty coil or low refrigerant.'), JSON_OBJECT('name', 'Condensing unit not starting', 'detail', 'Electrical faults, failed contactors or capacitors, tripped pressure switches or an overheating compressor can stop the outdoor unit running.'), JSON_OBJECT('name', 'Fan not running', 'detail', 'If the evaporator fan in the cellar fails, cold air stops circulating even when the condensing unit is running, so the cellar warms up.'), JSON_OBJECT('name', 'Water leaking from the evaporator', 'detail', 'A blocked condensate drain or tray can cause the cooler to drip onto barrels, gas bottles or the cellar floor.')), JSON_ARRAY(JSON_OBJECT('question', 'What temperature should a beer cellar be?', 'answer', 'Cask ale cellars are commonly kept around 11–13°C. Check your brewer''s guidance for your products.'), JSON_OBJECT('question', 'Why is my cellar cooler icing up?', 'answer', 'Low airflow, a defrost problem, a dirty coil or a refrigerant issue are the usual causes.'), JSON_OBJECT('question', 'Do you repair beer line coolers and python chillers?', 'answer', '[CONFIRM: state whether you work on beer line cooling / ice-bank chillers, or cellar cooling only.]'), JSON_OBJECT('question', 'Do you service cellar cooling systems?', 'answer', 'Yes — regular servicing helps catch problems early. [CONFIRM: maintenance offering.]')), '[CONFIRM BEFORE LAUNCH] Handling refrigerant in air conditioning and commercial refrigeration requires F-Gas certification. Add the certificate / company F-Gas number here.', '/images/cellar-cooler-repair-800.webp', 'Pub beer cellar with kegs connected to beer lines', 'Thermometer', 'Cellar Cooler Repair Feltham | Same-Day | HS Appliances', 'Beer cellar cooling repair for pubs in West London: cellar running warm, iced evaporators, condensing unit faults. Call 07777 372586.', 150, 0, 1);
INSERT INTO services (slug, name, menu_label, category, short_description, content, common_faults, faqs, compliance_note, image, image_alt, icon, meta_title, meta_description, sort_order, is_featured, is_active) VALUES ('ice-machine-repair', 'Ice Machine Repair', 'Ice Machine', 'commercial', 'Commercial ice machine repairs and cleaning — not making ice, small or cloudy cubes, slow production, leaks and scale build-up.', '<p>A bar, restaurant or hotel that runs out of ice notices straight away. Ice machines combine refrigeration, water supply, pumps, sensors and timing controls, and they''re unforgiving of hard water and poor hygiene. Many "breakdowns" turn out to be scale build-up, a blocked filter or a sensor that can''t detect ice properly, while others are refrigeration or electrical faults.</p>
<p>We repair, clean and descale commercial ice machines for businesses across Feltham and West London. We''ll find out why production has dropped or stopped and explain what''s needed to get it going again.</p>
<h2>Ice is food — hygiene matters</h2>
<p>Ice that goes into drinks is treated as food, so the machine that makes it needs cleaning and sanitising regularly. Slime and mould can grow in the water trough, distribution system and storage bin, and it isn''t always visible from the front.</p>
<p>Regular professional cleaning, following the manufacturer''s schedule, keeps ice safe and the machine working efficiently.</p>
<h2>Hard water and scale</h2>
<p>Most of West London has hard water. Scale forms quickly on ice machine parts, and it''s one of the main reasons machines lose output or stop altogether.</p>
<p>A suitable water filter or scale-inhibiting cartridge, changed on schedule, greatly reduces how often a machine needs descaling.</p>
<h2>Location and airflow</h2>
<p>Most smaller ice machines are air-cooled and need clear space around them to get rid of heat. Under a counter next to a dishwasher, or in a hot kitchen corridor, they work harder and make less ice.</p>
<p>Keeping the condenser clean and the vents clear makes a noticeable difference to output.</p>
<h2>Types of ice machine</h2>
<p>Self-contained under-counter machines make and store ice in one cabinet and are common in bars and smaller restaurants. Modular machines sit on top of a separate storage bin and make more ice for hotels and busy venues. Flake and nugget machines produce softer ice for food displays, fish counters and healthcare.</p>
<p>Each type works a little differently, but they share the same basics — water supply, refrigeration, harvest controls and drainage — and the same need for regular cleaning.</p>', JSON_ARRAY(JSON_OBJECT('name', 'Not making ice', 'detail', 'The water supply may be off or restricted, the inlet valve may have failed, the water pump may not be running, or there may be a refrigeration or control fault.'), JSON_OBJECT('name', 'Small, thin or cloudy cubes', 'detail', 'Low water pressure, a blocked filter, scale on the evaporator or water distribution system, or a faulty sensor can all affect the size and clarity of the ice.'), JSON_OBJECT('name', 'Slow production', 'detail', 'A dirty air-cooled condenser, a hot room, scale build-up or a refrigeration problem can make the machine produce far less ice than it''s rated for.'), JSON_OBJECT('name', 'Leaking water', 'detail', 'A blocked drain, a split hose, a stuck inlet valve or a cracked water trough can cause leaks around or under the machine.'), JSON_OBJECT('name', 'Scale build-up', 'detail', 'In hard-water areas like West London, limescale coats the evaporator plate, water pump and distribution tubes, reducing output and eventually stopping production.'), JSON_OBJECT('name', 'Ice tastes or smells bad', 'detail', 'This usually means the machine needs cleaning and sanitising, the water filter needs changing, or slime or mould has built up in the water system.')), JSON_ARRAY(JSON_OBJECT('question', 'How often should an ice machine be cleaned?', 'answer', 'Follow the manufacturer''s schedule — commonly every few months, and more often in hard-water areas or busy sites.'), JSON_OBJECT('question', 'Why is my ice machine making small cubes?', 'answer', 'Low water pressure, a blocked filter, scale build-up or a sensor issue are the common causes.'), JSON_OBJECT('question', 'Why does my ice taste strange?', 'answer', 'Usually the machine is overdue for cleaning and sanitising, or the water filter needs changing. It can also come from food odours in the room getting into the bin.'), JSON_OBJECT('question', 'Do you repair under-counter and modular ice machines?', 'answer', '[CONFIRM: the types of ice machine you work on.]')), NULL, '/images/ice-machine-repair-800.webp', 'Pile of clear ice cubes from a commercial ice machine', 'Snowflake', 'Ice Machine Repair Feltham | Same-Day | HS Appliances', 'Commercial ice machine repair & cleaning in West London — not making ice, small cubes, leaks, scale build-up. Call 07777 372586.', 160, 1, 1);

